import { observable, action, toJS, runInAction, computed, makeObservable } from "mobx";
import app from "@/store/app";
import ajax from "@/utils/ajax";
import globals, { dynamicCreateModule } from "@/environments/hoc";
import config from 'config';
import { addCSS, convertToTree, getSpecificValues, getUuid, treeMap } from "@/utils"
import _ from "lodash";
import { MenuItem, RouteProps } from "@/types/menu";
import { mainRoutes, adminRoutes } from "@code/routes";
import dayjs from "dayjs";
import tailwindcss from "./tailwindcss";
import dir from "./dir";
import file from '@/store/file';
import { IRoute } from "@code/types/route";
import lazyload from "@/utils/lazyload";
import { getArcoIcon } from "@/utils/icon";
import React from "react";
import language from "./language";
import userStore from '@code/store/user';
import pluginsStore from "@/store/plugins";
import { Message } from "@arco-design/web-react";
import { IfrmaeAppProps } from "@/types/iframe";


interface EnvConfig {
    history: any;
}

const win: IfrmaeAppProps = window as any;

class Store {
    pageMap: Record<string, any> = {};
    fileMap: Record<string, any> = {};
    pages: any[] = [];
    modules: any[] = [];
    plugins: any[] = [];
    languages: any[] = [];  // 所有多语言Keys


    @observable key = Date.now();
    @action updateKey = () => {
        this.key = Date.now();
    }

    // 首页路由地址
    @observable routes: IRoute[] = [];
    @action setRoutes = (list) => {
        const routeList = this.getTreeMenus(list)
        const result = treeMap(routeList, (o) => {
            const item = {
                name: o.name,
                key: o.path,
                path: o.path,
                isLayout: o.type == 'layout'? true: undefined,
                ignore: o.isShow? undefined : true,
                component: o.component,
                pageId: o.pageId,
            }
            if(!o.component && o.pageId) {
                item.component = lazyload(() => this.getPageComponent(o.pageId));
            }
            return item;
        })
        
        this.routes = result;
    }

    // 管理页路由地址
    @observable adminRoutes: IRoute[] = [];
    @action setAdminRoutes = (list) => {
        const result = treeMap(this.getTreeMenus(list), (o) => {
            return {
                name: o.name,
                key: o.path,
                path: o.path,
                ignore: o.isShow? undefined : true,
                component: o.pageId? lazyload(() => this.getPageComponent(o.pageId)) : undefined,
                icon: o.icon? React.createElement(getArcoIcon(o.icon), { }) : undefined,
            }
        })

        this.adminRoutes = result;
    }

    get adminMenu (){
        const loop = (list) => {
            return list.map((o) => {
                const item:any = {
                    path: o.path,
                    name: o.name,
                }
                if(o.children) item.children = loop(o.children);
                return item;
            })
        }
        const result = toJS(this.adminRoutes);
        return loop(result || []);
    }

    // 创建页面路径映射对象
    pagePathMap: Record<string, string[]> = {};

    getTreeMenus = (list: MenuItem[]) => {
        return getSpecificValues(convertToTree(
            list.map((o) => {
                return { 
                    ...o,
                    // 写入权限
                    requiredPermissions: o.authority? [{ resource: o.authority }] : undefined,
                    key: String(o.id),
                    originPath: o.path,
                }
            })
        ), (item, parentItem) => {
            if(!parentItem) return {
                ...item,
                paths: [item.path],
                path: item.path == '*'? '*' : `/${[item.path].filter((k) => !['/', '*'].includes(k)).join('/')}`,
            };
            let paths = [ ...parentItem.paths, item.path ];
            return {
                ...item,
                paths,
                path: item.path == '*'? '*' : `/${paths.filter((k) => !['/', '*'].includes(k)).join('/')}`,
            }
        })
    }



    /**
     * @title 获取页面Component
     * @param pageId 当前页面id
     * @param objs 覆盖当前globas 配置，用于admin 差异化
     */
    getPageComponent = async (pageId: string ) => {
        // console.log('getPageComponent', pageId, this.pageMap, this.fileMap)
        const fileKey = this.pageMap[pageId];
        const data = await this.fileMap[fileKey]();
        const key = `createPage_${pageId.replace(/\-/g, '')}`;
        const Element = data[key]();
        // console.log('Element', Element, this.fileMap);
        return { default: Element }
    }


    /**
     * 加载模块
     */
    loadModules = (moduleId: string, { jsxRender }: any) => {
        // 模块加载逻辑
        globals.state.mModules[moduleId] = dynamicCreateModule(jsxRender);
    }

    /**
     * 构建页面
     */
    buildPages = (pageId: string, { jsxRender }: any) => {
        // 页面构建逻辑
        this.pageMap[pageId] = pageId;
        // 模拟线上环境返回
        const key = `createPage_${pageId.replace(/\-/g, '')}`;
        this.fileMap[pageId] = async () => {
            return {
                [key]: () => {
                    return dynamicCreateModule(jsxRender);
                },
            }
        };
        if(this.pagePathMap[pageId]){
            // 同时更新对应页面路由comopnent参数
            _.set(mainRoutes, [...this.pagePathMap[pageId], 'component'], lazyload(() => this.getPageComponent(pageId)))
        }
    }


    activatePageModules = (pages, modules) => {
        // console.log('activatePageModules', hocConfig, globals, state)
        let cssStr = "";
        for (const module of modules) {
            globals.state.mModules[module.moduleId] = dynamicCreateModule(module.jsxRender);
            const { moduleId, nickname, name, extraInfo = {} } = module;
            if(extraInfo && extraInfo.cssStr){
                cssStr += `/** moduleId: ${moduleId}【${nickname || name}】 */\n ${extraInfo.cssStr}`
            }
        }
        for (const page of pages) {
            const { extraInfo = {}, id, title, jsxRender } = page;
            this.buildPages(page.id, { jsxRender });
            if(extraInfo && extraInfo.cssStr) {
                cssStr += `/** pageId: ${id}【${title}】 */\n${extraInfo.cssStr}`
            }
        }
        if(cssStr){
            // 写入样式
            addCSS(cssStr, getUuid("hash"));
        }
    }


    // 递归处理路由，记录页面路径
    processRoutes = (routes, parentPath = []) => {
        routes.forEach((route, index) => {
            let paths = [...parentPath, index];
            if (route.pageId) {
                this.pagePathMap[route.pageId] = paths;
            }
            if (route.children) {
                this.processRoutes(route.children, [...paths, 'children']);
            }
        });
    };

    /**
     * 项目加载成功后将数据写入到对应项目中
     */
    initEnv = async () => {
        // 写入main中路由
        for (const item of this.routes) {
            mainRoutes.push(item);
        }
        // 写入admin中路由
        for (const item of this.adminRoutes) {
            adminRoutes.push(item);
        }

        this.processRoutes(mainRoutes);
        this.processRoutes(adminRoutes);

        // 写入config
        const configuration = _.cloneDeep(app.extraInfo.configuration);
        if(configuration['login_bgUrl']){
            if(win.fileStore){  // 优先使用win资源
                configuration['login_bgUrl'] = win.fileStore.imgMap[configuration['login_bgUrl']];
            } else {
                configuration['login_bgUrl'] = file.imgMap[configuration['login_bgUrl']];
            }
        }

        Object.assign(config, _.omit(configuration, ['api_path']));
    }

    /**
     * 获取应用信息
     */
    init = async () => {
        const { plugins = {} } = app.info.extraInfo || {}
        const pluginList = Object.values(plugins).filter((o) => o.isActive);
        const pluginIds = pluginList.filter((o) => !o.version).map((o) => o.id);
        const pluginNode = {};
        // 获取应用信息
        const info = await ajax.post('/app/appInformation', {
            projectId: app.info.projectId,
            pluginIds
        }).then((data) => {
            const { modules, pages, menus, plugins, project } = data;
            // for (const plugin of plugins) {
            //     pluginNode[plugin.id] = plugin;
            // }
            this.plugins = plugins;
            this.activatePageModules(pages, modules);
            this.pages = pages;
            this.modules = modules;
            this.setRoutes(menus); // 设置web网站路由
            return data;
        })

        pluginsStore.setList(this.plugins.map((o) => _.assign(o, { pluginId: o.id })));
        await this.initAppProject()

        await this.initEnv();
        await language.reloadApp(this.languages)
    
        if(win.language){
            win.language.setStore(language.getStore());
        }
    }

    /**
     * 加载应用插件信息
     */
    initAppProject = async () => {

        const { projectId, projectReleaseVersion, extraInfo } = app.info;

        const pluginList = pluginsStore.pluginsList;

        // console.log('pluginList', pluginList,  extraInfo)
   
        this.languages = [];
        // 加载插件信息
        await Promise.all(
            [
                import(dir.project.getBuild(projectId, projectReleaseVersion)).then((res) => res.default),
                ...pluginList.map((o) => { 
                    // 优先使用选择的版本，没有情况下使用线上版本
                    return { ...o, version: extraInfo.plugins[o.pluginId]!.version ||  o.releaseVersion }
                }).filter((o) => Boolean(o.version)).map((o) => {
                    return import(dir.plugin.getBuild(o.pluginId, o.version)).then((res) => {
                        return res.default;
                    })
                })
            ]
        ).then((list) => {
            let adminMenus = [];
            // console.log('app-project-plugin-list', list)
            for (const item of list) {
                const { modules, pages, menus, languages = [] } = item;
                this.activatePageModules(pages, modules);
                // 加载所有页面信息
                this.pages = this.pages.concat(pages);
                this.modules = this.modules.concat(modules);
                this.languages = this.languages.concat(languages);
                adminMenus = adminMenus.concat(menus);
            }

            // 设置管理端admin 路由
            this.setAdminRoutes(adminMenus)

            // console.log('adminMenus', adminMenus, this.adminRoutes)
        })

        // if(this.languages.length){
        //     // 加载项目和插件多语言
        //     if(win.language){
        //         await win.language.reloadPreviewApp(Array.from(new Set(this.languages)));
        //     }
        // }
    }


    /**
     * 获取插件信息
     */
    setPluginData = async (data: any) => {
        const { modules, pages, menus } = data;
        this.activatePageModules(pages, modules)
        this.pages = this.pages.concat(pages);
        this.modules = this.modules.concat(modules);
        this.setAdminRoutes(menus);
        await this.initEnv();
    }


    /** 获取应用版本信息 */
    initVersion = async (version: string) => {
        // @ts-ignore
        await import(dir.app.getBuild(app.info.mark, version)).then((res) => {
            const data = res.default;
            runInAction(() => {
                this.activatePageModules(data.pages, data.modules);
                // 将版本信息内容合并到当前版本
                this.routes = data.routes;
                this.pages = data.pages;
                this.adminRoutes = data.adminRoutes
            })
        })
    }


    constructor() {
        makeObservable(this);
    }


    // 创建版本将会使用当前配置全部放入道json 文件中
    get exportJSON(){
        return {
            info: app.info,
            plugins: this.plugins,
            routes: this.routes,
            adminRoutes: this.adminRoutes,
            pages: this.pages,
            modules: this.modules,
        }
    }


    /**
     * 创建全局配置文件
     */
    createCssFileStr = (pages: any[], modules: any[]) => {
        let cssStr = '';
        for (const page of pages) {
            const { id, title, extraInfo } = page;
            if(extraInfo && extraInfo.cssStr){
                cssStr += `/** pageId: ${id}【${title}】 */\n${extraInfo.cssStr}`
            }
        }
        for (const module of modules) {
            const { id, name, nickname, extraInfo } = module;
            if(extraInfo && extraInfo.cssStr){
                cssStr += `/** moduleId: ${id}【${nickname || name}】 */\n ${extraInfo.cssStr}`
            }
        }
        return cssStr;
    }
    /**
     * 创建页面全局文件
     */
    createPageFileStr = (page: any) => {

        if(!page.jsxRender) return "";
        return `
            export function createPage_${page.id.replace(/\-/g, '')}(global){
                ${page.jsxRender}
            };
        `;
    }

    ids = {};
    getFileUuid(){  // 确保hash值不会重复
        let hash = getUuid("hash");
        while(this.ids[hash]){
            hash = getUuid("hash");
        }
        return `${getUuid('hash').slice(0,1)}${hash}`;
    }

    // 获取tailwindcss 样式文件
    getTailwindcss = async () => {
        const { routes, pages, adminRoutes, modules = [] } = this.exportJSON;
        let jsxStr = '';
        for (const item of pages) {
            jsxStr += item.jsxRender
        }
        for (const item of modules) {
            jsxStr += item.jsxRender;
        }
        const css = await tailwindcss.toCss(jsxStr);
        
        return css;
    }

    // 获取对应的文件包
    getAppFileInfo = async () => {
        const { routes, pages, adminRoutes, modules = [] } = this.exportJSON;
        let files = [];
        let pageMap: any = {};
        let pageObj = { content: "", fileId: getUuid() };
        for (const page of pages) {
            const pageStr = this.createPageFileStr(page);
            if(pageStr){
                pageObj.content += this.createPageFileStr(page);
                pageMap[page.id] = pageObj.fileId;
            }
            if(pageObj.content.length > 65536){
                // 大致判断当前页面内容是否超过了 64kb，没超过多个页面合并加载
                files.push(pageObj);
                pageObj = { content: "", fileId: getUuid() };
            }
        }
        if(pageObj.content.length){
            files.push(pageObj);
        }
        const date = dayjs().format("YYYY-MM-DD HH:mm:ss");
        const fileMap = {};
        // 创建全局js 文件
        let moduleStr = '';
        for (const item of modules) {
            if(item.jsxRender){
                moduleStr += `"${item.moduleId}": () => { //${item.nickname || item.name}\n ${item.jsxRender} },\n`;   
            }else {
                moduleStr += `"${item.moduleId}": () => { return null },\n`;
            }
        }
        let fileStr = '';
        for (const file of files) {
            const uuid = this.getFileUuid();
            fileMap[file.fileId] = uuid
            fileStr += `"${file.fileId}": () => import("./index.${uuid}.js"),\n`;
        }
        const cssStr = this.createCssFileStr(pages, modules);
        const appStr = `
            export function createApp(global){

                return {
                    date: "${date}",
                    routes: ${JSON.stringify(routes)},
                    adminRoutes: ${JSON.stringify(adminRoutes)},
                    pageMap: ${JSON.stringify(pageMap)},
                    fileMap: { ${fileStr} },
                    moduleNode: { ${moduleStr} }
                }
            }
        `

        return { cssStr, appStr, files, fileMap }
    }

    isOne = false;
    // 切换到xx用户
    changeLogin = (loginname) => {
        this.isOne = true;
        return ajax.post('/dev/UserLogin', {
            loginname,
        }).then((res) => {
            userStore.setInfo(res.data);
        })
    }

    autoLogin = () => {
        if(this.isOne) return;  // 自动登录逻辑只执行一次
        if(userStore.isLogin) return;
        this.changeLogin('admin').then((res) => {
            Message.success("已自动登录管理员账号")
        })
    }

}

export default new Store();